 "content": """"Color 2x2 blocks and L-triomino orientations in the ARC grid."""


def transform(grid):
    h, w = len(grid), len(grid[0])
    filled = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # The demonstrations establish color 1 for squares, and colors 2, 3,
    # and 4 for the observed L orientations (identified by their missing cell).
    shapes = {
        1: ((0, 0), (0, 1), (1, 0), (1, 1)),
        2: ((0, 1), (1, 0), (1, 1)),  # missing upper-left
        3: ((0, 0), (0, 1), (1, 1)),  # missing lower-left
        4: ((0, 0), (1, 0), (1, 1)),  # missing upper-right
    }
    placements = []
    for color, shape in shapes.items():
        max_r = h - 1
        max_c = w - 1
        for r in range(max_r):
            for c in range(max_c):
                cells = frozenset((r + dr, c + dc) for dr, dc in shape)
                if cells <= filled:
                    placements.append((color, cells))

    by_cell = {cell: [] for cell in filled}
    for placement in placements:
        for cell in placement[1]:
            by_cell[cell].append(placement)

    def search(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(piece <= remaining for piece in by_cell[p]))
        for color, cells in by_cell[cell]:
            if cells <= remaining:
                rest = search(remaining - cells)
                if rest is not None:
                    return [(color, cells)] + rest
        return None

    solution = search(filled)
    if solution is None:
        raise ValueError("No tiling using the demonstrated pieces")
    for color, cells in solution:
        for r, c in cells:
            out[r][c] = color
    return out
